@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#f5f7f6;background:#07141d;font-synthesis:none;--gold:#e5b75e;--muted:#a9b5b6;--panel:rgba(9,24,33,.88);--line:rgba(255,255,255,.13)}*{box-sizing:border-box}body{margin:0;min-width:320px;min-height:100vh;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer}#app{position:relative;width:100vw;height:100dvh;min-height:600px;overflow:hidden;background:#081820}#scene{position:absolute;inset:0;z-index:0}#scene canvas{display:block;width:100%;height:100%}.scene-vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:linear-gradient(90deg,rgba(5,15,21,.93) 0%,rgba(5,15,21,.76) 27%,rgba(5,15,21,.13) 66%,rgba(5,15,21,.25) 100%),linear-gradient(0deg,rgba(5,13,18,.84),transparent 30%,rgba(3,10,15,.36))}.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:82px;padding:0 4.5vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(4,13,18,.72),rgba(4,13,18,.06))}.brand{border:0;background:none;display:flex;align-items:center;gap:12px;padding:0;text-align:left}.brand-mark{width:37px;height:40px;border:2px solid var(--gold);color:var(--gold);font:900 29px 'Barlow Condensed';display:grid;place-items:center;transform:skew(-7deg);text-shadow:0 0 15px #e5b75e55}.brand-copy{display:grid;line-height:.9;letter-spacing:1.6px}.brand-copy b{font:700 11px 'Barlow Condensed';color:#d7dfdc}.brand-copy strong{font:900 25px 'Barlow Condensed';letter-spacing:2px}.season-chip{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;color:#d4dcda;font-size:10px;font-weight:700;letter-spacing:1.8px}.season-chip i{font-style:normal;color:var(--gold)}.live-dot{height:7px;width:7px;background:#d9ad54;border-radius:50%;box-shadow:0 0 12px #ddb454}.profile{display:flex;align-items:center;gap:10px;border:0;background:none;text-align:left}.profile-icon{width:36px;height:36px;border-radius:50%;border:1px solid #d5aa5a;color:var(--gold);display:grid;place-items:center;font-size:11px;font-weight:700}.profile b{font:700 12px 'Barlow Condensed';letter-spacing:1.1px}.profile small{display:block;color:#aab7b5;font-size:9px;letter-spacing:1.5px;margin-top:3px}.chevron{color:var(--gold);margin-left:7px}#main-ui{position:relative;z-index:2;height:100%;padding:110px 4.5vw 36px;display:flex;align-items:center}.home-layout{width:min(510px,47vw);animation:fade-in .5s ease both}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--gold);font-size:10px;font-weight:700;letter-spacing:2.4px;text-transform:uppercase}.eyebrow:before{content:'';height:1px;width:28px;background:var(--gold)}h1,h2,h3,p{margin-top:0}.hero-title{font:900 clamp(58px,7vw,100px)/.8 'Barlow Condensed';letter-spacing:-2px;margin:17px 0 14px;text-transform:uppercase;text-shadow:0 4px 24px #0007}.hero-title span{display:block;color:var(--gold)}.hero-desc{color:#c3cecc;font-size:13px;line-height:1.7;max-width:375px;margin-bottom:27px}.home-actions{display:grid;gap:9px;width:min(340px,100%)}.action-card{border:1px solid rgba(255,255,255,.17);background:linear-gradient(105deg,rgba(16,38,47,.92),rgba(14,32,39,.63));height:65px;padding:0 15px;display:flex;align-items:center;text-align:left;gap:13px;transition:.2s;position:relative;overflow:hidden}.action-card:after{content:'';position:absolute;inset:0;opacity:0;background:linear-gradient(90deg,#d9ac5233,transparent);transition:.2s}.action-card:hover{border-color:#d6ad61;transform:translateX(4px)}.action-card:hover:after{opacity:1}.action-icon{position:relative;z-index:1;width:35px;height:35px;display:grid;place-items:center;background:#d7ac5421;border:1px solid #d7ac5452;color:var(--gold);font-size:17px}.action-copy{position:relative;z-index:1;flex:1}.action-copy b{font:800 17px 'Barlow Condensed';letter-spacing:1px;display:block}.action-copy small{color:#a7b5b5;font-size:9px;letter-spacing:.7px}.action-arrow{position:relative;z-index:1;color:var(--go