ter-spacing:1.2px;margin-bottom:8px}.team-tile select,.select-control{width:100%;background:#10232b;color:#f4f4ef;border:1px solid #ffffff24;padding:10px;font:700 13px 'Barlow Condensed';letter-spacing:.5px;outline:none}.vs{color:var(--gold);font:800 18px 'Barlow Condensed'}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0}.form-field label{display:block;font-size:9px;color:#b5c1bf;letter-spacing:1.1px;margin-bottom:7px}.segmented{display:flex;gap:4px;padding:3px;border:1px solid #ffffff1b;background:#08191f}.segmented button{flex:1;border:0;background:transparent;color:#9daead;padding:8px 5px;font:700 10px 'Barlow Condensed';letter-spacing:.6px}.segmented button.active{background:#d5a94e;color:#121a1b}.choice-note{font-size:10px;color:#95a5a4;line-height:1.5;margin:8px 0 0}.game-preview{padding:23px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.preview-top{position:relative;z-index:1}.preview-kicker{font-size:9px;letter-spacing:2px;color:var(--gold);font-weight:700}.preview-matchup{font:900 35px/.95 'Barlow Condensed';margin:12px 0}.preview-matchup span{color:var(--gold)}.preview-detail{font-size:11px;color:#b9c7c4}.stadium-mini{position:absolute;inset:34% 0 0;opacity:.86;background:linear-gradient(180deg,transparent,#081c21),linear-gradient(0deg,#246345,#45834d);clip-path:polygon(5% 25%,95% 0,100% 100%,0 100%)}.stadium-mini:after{content:'';position:absolute;inset:15% 13% 5%;border:2px solid #d8d1a96b;background:repeating-linear-gradient(0deg,transparent 0 24px,#f5edbd99 25px 26px),linear-gradient(0deg,#19603f,#387a48)}.preview-bottom{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:12px}.primary-btn{border:0;background:var(--gold);color:#171a18;padding:13px 19px;font:900 14px 'Barlow Condensed';letter-spacing:1.4px;text-transform:uppercase;box-shadow:0 5px 22px #c7974433;transition:.2s}.primary-btn:hover{background:#f2ca75;transform:translateY(-1px)}.primary-btn.wide{width:100%;margin-top:14px}.mode-choice{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mode-card{min-height:130px;text-align:left;padding:17px;border:1px solid #ffffff24;background:#10242caa}.mode-card:hover,.mode-card.selected{border-color:var(--gold);background:#ad843322}.mode-card .mode-icon{font-size:22px;color:var(--gold)}.mode-card b{display:block;font:800 22px 'Barlow Condensed';margin-top:9px}.mode-card small{display:block;color:#aebcba;line-height:1.5;font-size:10px;margin-top:4px}.game-screen{position:absolute;inset:0;z-index:4;pointer-events:none}.game-screen button,.game-screen .interactive{pointer-events:auto}.scorebug{position:absolute;top:96px;left:50%;transform:translateX(-50%);width:min(450px,90vw);display:flex;background:rgba(7,18,24,.92);border:1px solid #ffffff2a;box-shadow:0 6px 25px #0007;align-items:center;justify-content:center;height:56px}.score-team{flex:1;text-align:center}.score-team b{font:800 20px 'Barlow Condensed';letter-spacing:1px}.score-team.home b{color:#efc568}.score-team small{font:700 16px 'Barlow Condensed';padding-left:8px}.score-center{height:100%;min-width:93px;background:#c9a04e;color:#15201e;display:grid;place-items:center;font:800 17px 'Barlow Condensed';letter-spacing:1px}.score-center small{display:block;font:700 8px 'DM Sans';letter-spacing:1px}.game-hud{position:absolute;left:4.5vw;top:104px;width:180px;padding:13px 14px;background:#07151edc;border-left:2px solid var(--gold)}.hud-kicker{font-size:8px;letter-spacing:1.8px;color:var(--gold);font-weight:700}.hud-down{font:800 22px 'Barlow Condensed';margin:2px 0}.hud-yard{font-size:10px;color:#b7c3c0}.game-controls{position:absolute;left:50%;transform:translateX(-50%);bottom:28px;display:flex;gap:7px;align-items:center}.control-hint{background:#091820dc;border:1px solid #ffffff35;padding:9px 12px;color:#dbe1dc;font-size:9px;letter-spacing:.5px;white-space:nowrap}.control-hint kbd{color:#e4bb65;font-weight:800}.game-buttons{position:absolute;right:4.5vw;bottom:25px;display:flex;gap:7px}.game-buttons button{padding:10px 12px;background:#091820df;border:1px solid #ffffff39;font-size:9px;font-weight:700;letter-spacing:1px}.game-buttons button:hover{border-color:var(--gold);color:var(--gold)}.play-call{position:absolute;top:170px;left:50%;transform:translateX(-50%);padding:9px 14px;background:#07151edb;color:#f6f1df;border:1px solid #ffffff27;font-size:10px;letter-spacing:1.6px;text-align:center}.play-call b{color:var(--gold);display:block;font:800 17px 'Barlow Condensed';letter-spacing:1px;margin-top:3px}.pass-targets{position:absolute;bottom:85px;left:50%;transform:translateX(-50%);display:flex;gap:7px}.pass-targets button{pointer-events:auto;padding:7px 12px;border:1px solid #ffffff47;background:#10242cdd;color:#fff;font-size:9px}.pass-targets button b{color:var(--gold);margin-right:5px}.toast{position:absolute;z-index:10;bottom:90px;left:50%;transform:translate(-50%,10px);opacity:0;pointer-events:none;background:#d8b15e;color:#17201f;padding:11px 18px;font:800 15px 'Barlow Condensed';letter-spacing:1px;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-shade{position:absolute;z-index:8;inset:0;background:#030a0dd9;display:grid;place-items:center;padding:18px}.modal{width:min(480px,100%);padding:25px;background:#0d2029;border:1px solid #ffffff2a;box-shadow:0 20px 70px #0009}.modal h2{font:900 37px 'Barlow Condensed';margin:8px 0}.modal p{font-size:12px;line-height:1.65;color:#b5c3c0}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.wide-panel{padding:20px;max-height:min(64vh,560px);overflow:auto}.data-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.week-list{display:grid;gap:6px}.week-row{display:grid;grid-template-columns:62px 1fr 65px;align-items:center;padding:10px;background:#10232b;border:1px solid #ffffff17;font-size:11px}.week-row.current{border-color:var(--gold)}.week-row small{color:#a3b2b0}.week-row b{font:700 14px 'Barlow Condensed'}.stat-card{padding:15px;background:#10232b;border:1px solid #ffffff17;margin-bottom:8px}.stat-card small{display:block;color:#a8b7b4;font-size:9px;letter-spacing:1px}.stat-card b{font:800 26px 'Barlow Condensed';color:var(--gold)}.roster-row{display:grid;grid-template-columns:38px 1fr 50px;align-items:center;gap:10px;padding:10px;border-bottom:1px solid #ffffff17}.jersey{width:32px;height:32px;background:#d0a54e;color:#18201f;display:grid;place-items:center;font:800 17px 'Barlow Condensed'}.roster-row b{font:700 14px 'Barlow Condensed'}.roster-row small{display:block;color:#9badaa;font-size:9px}.ovr{text-align:right;font:800 19px 'Barlow Condensed';color:#e5b75e}.season-side .primary-btn{margin-top:12px}.mobile-controls{display:none}
@keyframes fade-in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:850px){.topbar{height:68px;padding:0 18px}.season-chip{display:none}.profile b,.profile small{display:none}#main-ui{padding:88px 20px 28px}.scene-vignette{background:linear-gradient(90deg,rgba(5,15,21,.9),rgba(5,15,21,.52) 60%,rgba(5,15,21,.25)),linear-gradient(0deg,rgba(5,13,18,.9),transparent 42%)}.home-layout{width:min(500px,80vw)}.right-rail{display:none}.quick-grid{grid-template-columns:1fr;max-height:70vh;overflow:auto}.game-preview{min-height:200px}.game-screen .game-hud{top:160px;left:14px;width:145px}.scorebug{top:80px}.game-controls{bottom:86px}.game-buttons{right:12px;bottom:18px}.game-buttons button{padding:9px}.control-hint:nth-child(n+3){display:none}.screen-heading h1{font-size:46px}.wide-panel{max-height:68vh}}
@media(max-width:560px){#app{min-height:560px}.brand-mark{width:33px;height:35px;font-size:24px}.brand-copy strong{font-size:21px}.home-layout{width:100%}.hero-title{font-size:64px}.hero-desc{font-size:12px;max-width:310px}.home-actions{width:100%;max-width:360px}.action-card{height:59px}.home-bottom{font-size:8px;gap:7px}.home-bottom span+span{padding-left:7px}.screen-wrap{justify-content:flex-start;padding-top:2px}.screen-heading{margin-bottom:13px}.screen-heading h1{font-size:39px}.screen-heading p{font-size:10px;max-width:240px}.back-btn{padding:9px 10px;font-size:9px}.config-panel{padding:15px}.team-row{gap:7px}.team-tile{padding:10px 8px}.team-tile select{font-size:11px;padding:8px 5px}.form-row{gap:8px}.segmented button{font-size:9px;padding:7px 3px}.game-preview{min-height:185px;padding:17px}.preview-matchup{font-size:29px}.mode-card{padding:12px;min-height:122px}.mode-card b{font-size:19px}.scorebug{height:48px;width:min(370px,96vw)}.score-team b{font-size:16px}.score-team small{font-size:14px}.score-center{min-width:75px;font-size:15px}.game-screen .game-hud{top:137px;padding:9px 10px;width:128px}.hud-down{font-size:19px}.play-call{top:195px;font-size:9px}.game-controls{bottom:77px;gap:4px}.control-hint{padding:7px 8px;font-size:8px}.game-buttons{bottom:12px;left:10px;right:10px;justify-content:flex-end}.game-buttons button{font-size:8px;padding:8px}.pass-targets{bottom:119px}.data-grid{grid-template-columns:1fr}.wide-panel{padding:13px}.mobile-controls{display:block;position:absolute;pointer-events:auto;left:16px;bottom:74px;width:108px;height:108px}.mobile-controls button{position:absolute;width:37px;height:37px;border:1px solid #ffffff66;background:#0a1a22d9;color:#f0c767;font-size:16px}.mobile-controls .up{top:0;left:35px}.mobile-controls .left{top:35px;left:0}.mobile-controls .right{top:35px;right:0}.mobile-controls .down{bottom:0;left:35px}}

import * as THREE from 'three';
import './style.css';

const teams = [
  {name:'Legion High', short:'LEGION', city:'LEGION CITY', mascot:'KNIGHTS', color:'#d5a847', dark:'#14232a', rating:84, record:'0–0', logo:'L'},
  {name:'Cedar Ridge', short:'CEDAR RIDGE', city:'CEDAR RIDGE', mascot:'WOLVES', color:'#c84d46', dark:'#252b31', rating:79, record:'0–0', logo:'C'},
  {name:'Westfield Prep', short:'WESTFIELD', city:'WESTFIELD', mascot:'HAWKS', color:'#4d9a83', dark:'#142b2c', rating:76, record:'0–0', logo:'W'},
  {name:'North Valley', short:'NORTH VALLEY', city:'NORTH VALLEY', mascot:'BEARS', color:'#5377b6', dark:'#182337', rating:82, record:'0–0', logo:'N'},
  {name:'Pine Creek', short:'PINE CREEK', city:'PINE CREEK', mascot:'EAGLES', color:'#a36db3', dark:'#292134', rating:74, record:'0–0', logo:'P'}
];
const roster = [
  ['Mason Cole','QB',12,88],['Darius King','RB',4,84],['Eli Brooks','WR',11,86],['Noah Bennett','WR',7,81],['Carter Hayes','TE',85,78],['Leo Martin','LT',72,83],['Caleb Young','C',55,80],['Jackson Reed','MLB',52,85],['Andre Lewis','CB',2,82],['Owen Price','FS',20,79]
];
const state={screen:'home',mode:'Quick Game',home:0,away:1,weather:'Clear',difficulty:'Varsity',quarterLength:5,watch:false,practice:false,quarter:1,clock:300,homeScore:0,awayScore:0,down:1,toGo:10,spot:25,offense:'home',phase:'pre-snap',play:'I-Formation · Power',gameOver:false,possessions:0,seasonWeek:1,wins:0,losses:0,career:{prestige:2,points:3},started:false,ballCarrier:null,passTarget:null,ballFlight:null,driveStart:25,selectedTab:'Home'};
const app=document.querySelector('#app'), main=document.querySelector('#main-ui'), sceneRoot=document.querySelector('#scene'), toastEl=document.querySelector('#toast');
let toastTimer;
function toast(msg){toastEl.textContent=msg;toastEl.className='toast show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.className='toast',1800)}

// Three-dimensional Legion High Stadium — one permanent home field used by every mode.
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; sceneRoot.appendChild(renderer.domElement);
const scene=new THREE.Scene(); scene.background=new THREE.Color('#76909a'); scene.fog=new THREE.FogExp2('#82979a',.0036);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,450); camera.position.set(0,69,105); camera.lookAt(0,0,-1);
const hemi=new THREE.HemisphereLight('#cfdfdf','#1c2a22',2.1); scene.add(hemi);
const moon=new THREE.DirectionalLight('#fff1d2',3.1); moon.position.set(-38,72,35); moon.castShadow=true; moon.shadow.mapSize.set(2048,2048); moon.shadow.camera.left=-90; moon.shadow.camera.right=90; moon.shadow.camera.top=100; moon.shadow.camera.bottom=-100; moon.shadow.bias=-.0002; scene.add(moon);
const fill=new THREE.DirectionalLight('#8eb6cb',1.25); fill.position.set(40,40,-60); scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const grassMat=mat('#316b45'), darkGrass=mat('#2a5c3c'), white=mat('#e6e1ca'), concrete=mat('#788386'), metal=mat('#4a585a',.5,.55), goldMat=mat('#dbb65f',.55,.18), navyMat=mat('#101f27'), glass= new THREE.MeshStandardMaterial({color:'#293d45',roughness:.25,metalness:.45,emissive:'#233942',emissiveIntensity:.3});
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function stadiumText(text,size,color='#e7d09c'){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;const c=canvas.getContext('2d');c.fillStyle=color;c.font=`900 ${size}px Arial`;c.textAlign='center';c.textBaseline='middle';c.fillText(text,256,64);const tex=new THREE.CanvasTexture(canvas);tex.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide})}
function addBillboard(parent,text,x,y,z,w,h,rotation=0){const mesh=new THREE.Mesh(new THREE.PlaneGeometry(w,h),stadiumText(text,64));mesh.position.set(x,y,z);mesh.rotation.y=rotation;parent.add(mesh);return mesh}
// Grounds and the regulation 100 x 53 1/3 yard field.
box(scene,0,-1.2,0,190,1.1,220,mat('#293c37'),false);
box(scene,0,-.52,0,53.33,.16,120,grassMat,false);
for(let i=0;i<20;i++){const z=-47.5+i*5;box(scene,0,-.425,z,53.2,.015,4.96,i%2?grassMat:darkGrass,false)}
// Yard stripes, hash marks, sideline boundaries and numbers.
for(let y=-50;y<=50;y+=5){box(scene,0,-.405,y,52.4,.035,.15,white,false);for(const x of [-23.6,23.6])box(scene,x,-.4,y,2.4,.035,.15,white,false);for(const x of [-17.78,17.78])box(scene,x,-.397,y,.11,.04,.68,white,false)}
for(const x of [-26,26])box(scene,x,-.38,0,.24,.1,120,white,false);
for(const z of [-55,55])box(scene,0,-.38,z,53.2,.1,.22,white,false);
for(let z=-40;z<=40;z+=10){if(z===0)continue;const n=String(50-Math.abs(z));for(const side of [-1,1]){const m=new THREE.Mesh(new THREE.PlaneGeometry(3,2),stadiumText(n,72,'#e1ddc7'));m.rotation.x=-Math.PI/2;m.rotation.z=side===-1?Math.PI:0;m.position.set(side*22,-.365,z);scene.add(m)}}
// End zones remain personalized while the permanent stadium bowl stays Legion High.
