 const legs=[];for(let s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.43,4,6),pants);leg.position.set(s*.21,.19,0);leg.castShadow=true;root.add(leg);legs.push(leg);const sock=cylinder(root,s*.21,.12,.025,.11,.12,.22,white,8);}
