function updateFieldPaint(){const home=teams[state.home],away=teams[state.away];endHome.material.color.set(home.dark);endAway.material.color.set(away.dark);homeEndText.material.dispose();homeEndText.material=stadiumText(home.short,74);awayEndText.material.dispose();awayEndText.material=stadiumText(away.mascot,70);}

const keys=new Set();let aiTimer=0,simAccumulator=0,weatherParticles=null;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space'&&state.screen==='game')snapBall();if(e.code==='Escape'&&state.screen==='game')pauseGame();if(/^Digit[1-4]$/.test(e.code)&&state.screen==='game'&&state.phase==='throwing')throwTo(+e.code.slice(-1)-1);});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

function startMode(watch=false){state.watch=watch;state.practice=state.mode==='Practice';createTeamsOnField();state.screen='game';main.innerHTML=gameUI();if(state.practice){state.quarter=0;state.clock=0;state.homeScore=0;state.awayScore=0;state.phase='pre-snap';state.spot=25;state.down=1;state.toGo=10;toast('PRACTICE FIELD · WORK THE PLAY');}else toast(watch?'AI BROADCAST MODE':'FRIDAY NIGHT · GAME ON');camera.position.set(0,65,101);camera.lookAt(0,0,0);}
function gameUI(){const isPractice=state.practice;return `<div class="game-screen"><div class="scorebug"><div class="score-team home"><b>${teams[state.home].short}</b><small id="home-score">0</small></div><div class="score-center"><span id="game-clock">Q1&nbsp; 5:00</span><small>LEGION HIGH</small></div><div class="score-team"><b>${teams[state.away].short}</b><small id="away-score">0</small></div></div><div class="game-hud"><div class="hud-kicker">${isPractice?'PRACTICE · OFFENSE':`LEGION HIGH · ${state.offense==='home'?'OFFENSE':'DEFENSE'}`}</div><div class="hud-down" id="down-line">1ST &amp; 10</div><div class="hud-yard" id="yard-line">${yardLabel()}</div></div><div class="play-call" id="play-call">${state.watch?'AI COACHING':isPractice?'PRACTICE REP':state.play}<b id="phase-label">${state.watch?'WATCH THE DRIVE':'SPACE · SNAP THE BALL'}</b></div>${!state.watch&&!isPractice?`<div class="pass-targets" id="pass-targets" style="display:none"><button data-action="throw" data-target="0"><b>1</b> WIDE LEFT</button><button data-action="throw" data-target="1"><b>2</b> SLOT</button><button data-action="throw" data-target="2"><b>3</b> WIDE RIGHT</button><button data-action="throw" data-target="3"><b>4</b> BACK</button></div>`:''}<div class="game-controls"><span class="control-hint"><kbd>W A S D</kbd> MOVE</span><span class="control-hint"><kbd>SHIFT</kbd> SPRINT</span><span class="control-hint"><kbd>SPACE</kbd> SNAP / HUSTLE</span><span class="control-hint"><kbd>1–4</kbd> PASS</span></div><div class="mobile-controls"><button class="up" data-move="up">▲</button><button class="left" data-move="left">◀</button><button class="right" data-move="right">▶</button><button class="down" data-move="down">▼</button></div><div class="game-buttons"><button data-action="playbook">▤ &nbsp;PLAY</button><button data-action="camera">◉ &nbsp;CAMERA</button><button data-action="stats">▥ &nbsp;STATS</button><button data-action="pause">Ⅱ &nbsp;PAUSE</button></div></div>`}
function yardLabel(){const yard=Math.max(1,Math.min(99,Math.round(state.spot)));return `${state.offense==='home'?'LEGION':'VISITORS'} ${yard} · ${state.toGo} TO GO`}
function clockString(){const m=Math.floor(Math.max(0,state.clock)/60),s=Math.max(0,state.clock)%60;return `${m}:${String(Math.floor(s)).padStart(2,'0')}`}
function updateHUD(){const el=document.querySelector('#down-line');if(el)el.innerHTML=state.practice?'PRACTICE REP':`${state.down}${state.down===1?'ST':state.down===2?'ND':state.down===3?'RD':'TH'} &amp; ${Math.max(1,Math.ceil(state.toGo))}`;const y=document.querySelector('#yard-line');if(y)y.textContent=yardLabel();const hs=document.querySelector('#home-score');if(hs)hs.textContent=state.homeScore;const as=document.querySelector('#away-score');if(as)as.textContent=state.awayScore;const cl=document.querySelector('#game-clock');if(cl)cl.innerHTML=state.practice?'TRAINING':`Q${state.quarter}&nbsp; ${clockString()}`;const ph=document.querySelector('#phase-label');if(ph)ph.textContent=state.phase==='pre-snap'?'SPACE · SNAP THE BALL':state.phase==='throwing'?'PRESS 1–4 TO PASS':state.phase==='live'?'BREAK THE TACKLE':state.phase==='dead'?'SPACE · NEXT PLAY':state.watch?'AI SIMULATION':'';const call=document.querySelector('#play-call');if(call){const tit=state.watch?'AI COACHING':state.practice?'PRACTICE REP':state.play;call.childNodes[0].textContent=tit}const targets=document.querySelector('#pass-targets');if(targets)targets.style.display=state.phase==='throwing'?'flex':'none';}

// Playable football state machine shared by Play and Watch: snap, move, pass, tackle, down, turnover, score.
function snapBall(){if(state.screen!=='game')return;if(state.phase==='pre-snap'||state.phase==='dead'){if(state.gameOver){showEndgame();return}state.phase='live';state.ballCarrier=state.offensePlayers[8];state.selected=state.ballCarrier;ball.position.copy(state.ballCarrier.pos).add(new THREE.Vector3(0,1.35,.4));if(state.watch){state.aiDelay=0;toast('AI OFFENSE · POWER RUN')}else if(!state.practice){toast('SNAP! FIND A LANE');}else toast('REP LIVE · MAKE YOUR MOVE');updateHUD();return}if(state.phase==='live'&&!state.practice&&!state.watch&&state.offense==='home'){state.phase='throwing';updateHUD();toast('RECEIVERS RELEASED · PICK A TARGET')}}
function throwTo(index){if(state.phase!=='throwing')return;const receivers=[state.offensePlayers[10],state.offensePlayers[7],state.offensePlayers[6],state.offensePlayers[9]];state.passTarget=receivers[index];state.ballFlight={from:ball.position.clone(),to:state.passTarget.pos.clone().add(new THREE.Vector3(0,1.8,-1)),t:0,duration:.85,index};state.phase='pass-flight';updateHUD();}
function nextPlay(reason,turnover=false){if(state.phase==='dead'&&reason==='dead')return;state.phase='dead';state.ballCarrier=null;state.ballFlight=null;if(ball)ball.position.set(0,.35,0);if(state.practice){state.down++;state.toGo=10;state.spot=25;setTimeout(()=>{if(state.screen==='game'){state.phase='pre-snap';updateHUD()}},900);toast('REP COMPLETE · RUN IT AGAIN');updateHUD();return}
 if(turnover){state.offense=state.offense==='home'?'away':'home';state.spot=100-state.spot;state.down=1;state.toGo=10;toast('TURNOVER ON DOWNS · CHANGE OF POSSESSION');resetFormations();updateHUD();return}
 if(state.spot>=100){if(state.offense==='home')state.homeScore+=7;else state.awayScore+=7;toast('TOUCHDOWN! SIX FOR THE HOME CROWD');state.phase='score';state.gameOver=false;updateHUD();setTimeout(()=>{if(state.screen==='game'){kickoff();updateHUD()}},1800);return}
 if(state.spot<=0){if(state.offense==='home')state.awayScore+=2;else state.homeScore+=2;toast('SAFETY · DEFENSE GETS TWO');kickoff();updateHUD();return}
 if(state.spot>=state.driveStart+state.toGo){state.down=1;state.toGo=10;state.driveStart=state.spot;toast('FIRST DOWN · MOVE THE CHAINS')}else if(state.down>=4){if(state.spot<65&&state.down===4&&Math.random()<.54){if(state.offense==='home')state.homeScore+=3;else state.awayScore+=3;toast('FIELD GOAL IS GOOD · THREE POINTS');kickoff();updateHUD();return}state.offense=state.offense==='home'?'away':'home';state.spot=100-state.spot;state.down=1;state.toGo=10;state.driveStart=state.spot;toast('TURNOVER ON DOWNS · CHANGE OF POSSESSION');resetFormations();updateHUD();return}else{state.down++;state.toGo=Math.max(1,state.toGo-(state.spot-state.lastSpot));state.driveStart=state.spot}
 resetFormations();updateHUD();}
function kickoff(){state.offense=state.offense==='home'?'away':'home';state.spot=25;state.driveStart=25;state.down=1;state.toGo=10;state.phase='pre-snap';state.possessions++;resetFormations();if(state.quarter>=4&&state.clock<=0){state.gameOver=true;showEndgame()} }
function resetFormations(){const off=state.offensePlayers,def=state.defensePlayers;if(!off||!def)return;const direction=state.offense==='home'?-1:1;const line=0;off.forEach((p,i)=>{const slots=[[-18,1],[-12,1],[-6,1],[0,1],[6,1],[12,1],[18,1],[-3,4],[0,7],[12,8],[-14,9]][i];p.pos.set(slots[0],.02,slots[1]);p.root.rotation.y=direction<0?0:Math.PI});def.forEach((p,i)=>{const slots=[[-18,-2],[-12,-2],[-6,-2],[0,-2],[6,-2],[12,-2],[18,-2],[-14,-8],[-5,-7],[6,-8],[16,-8]][i];p.pos.set(slots[0],.02,slots[1]);p.root.rotation.y=direction<0?Math.PI:0});state.selected=state.offense===state.home?off[8]:def[7];state.phase='pre-snap';state.driveStart=state.spot;updateHUD()}
function endQuarter(){if(state.practice)return;if(state.quarter<4){state.quarter++;state.clock=state.quarterLength*60;toast(`END OF QUARTER · ${state.homeScore}–${state.awayScore}`)}else{state.gameOver=true;showEndgame()}}
function showEndgame(){state.phase='dead';const won=state.homeScore>=state.awayScore;modal(`${won?'VICTORY AT LEGION HIGH':'FINAL WHISTLE'}`,`${teams[state.home].name} ${state.homeScore} · ${state.awayScore} ${teams[state.away].name}`,`The Friday night lights are still shining at Legion High Stadium. ${won?'The Knights take another step toward the postseason.':'Every Friday brings another chance to grow.'}`,[{label:'RETURN TO HOME',action:'home',primary:true},{label:'PLAY AGAIN',action:'replay'}]);}
function movePlayer(dt){if(!state.selected||state.phase!=='live'||state.watch)return;const p=state.selected;let x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0);if(!x&&!z)return;const v=new THREE.Vector3(x,0,z).normalize();const sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');p.pos.addScaledVector(v,p.speed*(sprint?1.55:1)*dt);p.pos.x=THREE.MathUtils.clamp(p.pos.x,-24,24);p.pos.z=THREE.MathUtils.clamp(p.pos.z,-55,55);p.root.rotation.y=Math.atan2(v.x,v.z);p.phase+=dt*13;p.legs[0].rotation.x=Math.sin(p.phase)*.65;p.legs[1].rotation.x=-Math.sin(p.phase)*.65;if(state.ballCarrier===p)ball.position.copy(p.pos).add(new THREE.Vector3(.2,1.36,-.18));}
function aiMove(dt){if(state.phase!=='live')return;const carrier=state.ballCarrier;if(!carrier)return;const attack=state.offense==='home'?-1:1;if(state.watch){carrier.pos.z+=attack*carrier.speed*dt*.69;carrier.pos.x+=Math.sin(performance.now()/700)*dt*1.1;}else if(state.offense==='away'){carrier.pos.z+=attack*carrier.speed*dt*.58;carrier.pos.x+=Math.sin(performance.now()/600)*dt*.6;}
 const defense=state.defensePlayers;for(const p of defense){const dx=carrier.pos.x-p.pos.x,dz=carrier.pos.z-p.pos.z,dist=Math.hypot(dx,dz);if(dist<20&&dist>.9){p.pos.x+=dx/dist*dt*(p.speed*.55);p.pos.z+=dz/dist*dt*(p.speed*.55);p.root.rotation.y=Math.atan2(dx,dz)}if(dist<1.6){if(Math.random()<dt*2.7){state.lastSpot=state.spot;state.spot=Math.max(1,Math.min(99,state.spot+Math.abs(carrier.pos.z)*.24));nextPlay('tackle');return}}}
 const advance=Math.max(0,Math.abs(carrier.pos.z));if(advance>state.toGo||Math.abs(carrier.pos.z)>28){state.lastSpot=state.spot;state.spot=Math.min(100,state.spot+Math.max(2,advance*.36));if(advance>27)state.spot=Math.min(100,state.spot+28);nextPlay('tackle');return}
 if(state.watch||state.offense==='away'){aiTimer+=dt;if(aiTimer>4.5+Math.random()*2){aiTimer=0;state.lastSpot=state.spot;state.spot=Math.min(100,state.spot+Math.max(2,Math.random()*12));nextPlay('tackle')}}}
