 function tick(){requestAnimationFrame(tick);const dt=Math.min(.04,clock3.getDelta());if(state.screen==='game'){movePlayer(dt);aiMove(dt);updateBall(dt);updateWeather(dt);if(!state.practice&&state.phase==='live'&&!state.watch){state.clock=Math.max(0,state.clock-dt);if(state.clock<=0)endQuarter();}simAccumulator+=dt;if(simAccumulator>.35){simAccumulator=0;updateHUD();}}
  for(const p of players){if(p.active){p.phase+=dt*(state.phase==='live'?8:2);if(state.phase==='live'&&p!==state.selected){p.legs[0].rotation.x=Math.sin(p.phase)*.18;p.legs[1].rotation.x=-Math.sin(p.phase)*.18}}}
