function snapBall(){if(state.screen!=='game')return;if(state.phase==='pre-snap'||state.phase==='dead'){if(state.gameOver){showEndgame();return}state.phase='live';const offensePlayers=state.offense==='home'?state.offensePlayers:state.defensePlayers;const defensePlayers=state.offense==='home'?state.defensePlayers:state.offensePlayers;state.ballCarrier=offensePlayers[8];state.selected=state.watch?state.ballCarrier:(state.offense==='home'||state.practice?state.ballCarrier:defensePlayers[7]);state.playStartZ=state.ballCarrier.pos.z;ball.position.copy(state.ballCarrier.pos).add(new THREE.Vector3(0,1.35,.4));if(state.watch)toast('AI OFFENSE · POWER RUN');else if(!state.practice)toast(state.offense==='home'?'SNAP! FIND A LANE':'DEFENSE · CLOSE THE GAP');else toast('REP LIVE · MAKE YOUR MOVE');updateHUD();return}if(state.phase==='live'&&!state.practice&&!state.watch&&state.offense==='home'){state.phase='throwing';updateHUD();toast('RECEIVERS RELEASED · PICK A TARGET')}}
