import * as THREE from 'three';
import './style.css';

const teams = [
  {name:'Legion High', short:'LEGION', city:'LEGION CITY', mascot:'KNIGHTS', color:'#d5a847', dark:'#14232a', rating:84, record:'0–0', logo:'L'},
  {name:'Cedar Ridge', short:'CEDAR RIDGE', city:'CEDAR RIDGE', mascot:'WOLVES', color:'#c84d46', dark:'#252b31', rating:79, record:'0–0', logo:'C'},
  {name:'Westfield Prep', short:'WESTFIELD', city:'WESTFIELD', mascot:'HAWKS', color:'#4d9a83', dark:'#142b2c', rating:76, record:'0–0', logo:'W'},
  {name:'North Valley', short:'NORTH VALLEY', city:'NORTH VALLEY', mascot:'BEARS', color:'#5377b6', dark:'#182337', rating:82, record:'0–0', logo:'N'},
  {name:'Pine Creek', short:'PINE CREEK', city:'PINE CREEK', mascot:'EAGLES', color:'#a36db3', dark:'#292134', rating:74, record:'0–0', logo:'P'}
];
const roster = [
  ['Mason Cole','QB',12,88],['Darius King','RB',4,84],['Eli Brooks','WR',11,86],['Noah Bennett','WR',7,81],['Carter Hayes','TE',85,78],['Leo Martin','LT',72,83],['Caleb Young','C',55,80],['Jackson Reed','MLB',52,85],['Andre Lewis','CB',2,82],['Owen Price','FS',20,79]
];
const state={screen:'home',mode:'Quick Game',home:0,away:1,weather:'Clear',difficulty:'Varsity',quarterLength:5,watch:false,practice:false,quarter:1,clock:300,homeScore:0,awayScore:0,down:1,toGo:10,spot:25,offense:'home',phase:'pre-snap',play:'I-Formation · Power',gameOver:false,possessions:0,seasonWeek:1,wins:0,losses:0,career:{prestige:2,points:3},started:false,ballCarrier:null,passTarget:null,ballFlight:null,driveStart:25,selectedTab:'Home'};
const app=document.querySelector('#app'), main=document.querySelector('#main-ui'), sceneRoot=document.querySelector('#scene'), toastEl=document.querySelector('#toast');
let toastTimer;
function toast(msg){toastEl.textContent=msg;toastEl.className='toast show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.className='toast',1800)}

// Three-dimensional Legion High Stadium — one permanent home field used by every mode.
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; sceneRoot.appendChild(renderer.domElement);
const scene=new THREE.Scene(); scene.background=new THREE.Color('#76909a'); scene.fog=new THREE.FogExp2('#82979a',.0036);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,450); camera.position.set(0,69,105); camera.lookAt(0,0,-1);
