function makePlayer(teamIndex,number,pos,role='field'){const team=teams[teamIndex];const root=new THREE.Group();root.position.set(pos.x,.02,pos.z);scene.add(root);const jersey=mat(team.color,.62),pants=mat(team.dark,.72),skin=mat(['#a66f4c','#d49a70','#7c5039','#e0b48d'][number%4]),helmet=mat(team.color,.34,.12),dark=mat('#182127',.4,.15),gold=mat('#d7ba78',.45,.24);
