 const shoulders=new THREE.Mesh(new THREE.SphereGeometry(.55,10,8),jersey);shoulders.position.y=1.53;shoulders.scale.set(1.34,.54,.76);shoulders.castShadow=true;root.add(shoulders);
 const belly=new THREE.Mesh(new THREE.CylinderGeometry(.27,.34,.42,8),pants);belly.position.y=.61;root.add(belly);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),skin);head.position.set(0,1.94,.04);head.castShadow=true;root.add(head);
 const cap=new THREE.Mesh(new THREE.SphereGeometry(.31,12,7,0,Math.PI*2,0,Math.PI*.61),helmet);cap.position.set(0,2.02,.04);root.add(cap);
 const visor=box(root,0,1.99,.31,.48,.12,.17,helmet);visor.rotation.x=.15;
 for(let s of [-1,1]){const bar=cylinder(root,s*.24,1.86,.34,.035,.035,.49,gold,7);bar.rotation.z=s*.35;const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.16,.42,4,6),jersey);arm.position.set(s*.56,1.14,.02);arm.rotation.z=s*-.23;arm.castShadow=true;root.add(arm);const glove=new THREE.Mesh(new THREE.SphereGeometry(.14,8,6),dark);glove.position.set(s*.59,.87,.09);root.add(glove)}
 const legs=[];for(let s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.43,4,6),pants);leg.position.set(s*.21,.19,0);leg.castShadow=true;root.add(leg);legs.push(leg);const sock=cylinder(root,s*.21,.12,.025,.11,.12,.22,white,8);}
 const num=document.createElement('canvas');num.width=128;num.height=128;const c=num.getContext('2d');c.fillStyle='#f7f1df';c.font='900 72px Arial';c.textAlign='center';c.textBaseline='middle';c.fillText(String(number),64,64);const tex=new THREE.CanvasTexture(num);tex.colorSpace=THREE.SRGBColorSpace;const decal=new THREE.Mesh(new THREE.PlaneGeometry(.32,.34),new THREE.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false}));decal.position.set(0,1.18,.34);root.add(decal);
 const player={root,teamIndex,number,pos:root.position,legs,role,velocity:new THREE.Vector3(),speed:4.7+(number%3)*.35,active:true,phase:Math.random()*5};players.push(player);return player}
