 const defensePos=[[-18,-2],[-12,-2],[-6,-2],[0,-2],[6,-2],[12,-2],[18,-2],[-14,-8],[-5,-7],[6,-8],[16,-8]];
 defensePos.forEach((v,i)=>makePlayer(def,[90,95,98,91,99,94,97,52,54,2,20][i],{x:v[0],z:v[1]},['DL','DL','DL','DL','DL','DL','DL','LB','LB','CB','S'][i]));
 state.offensePlayers=players.slice(0,11);state.defensePlayers=players.slice(11);state.selected=state.offensePlayers[8];state.play='I-Formation · Power';
