 function aiMove(dt){if(state.phase!=='live')return;const carrier=state.ballCarrier;if(!carrier)return;const attack=state.offense==='home'?-1:1;const defense=state.offense==='home'?state.defensePlayers:state.offensePlayers;if(state.watch||state.offense==='away'){carrier.pos.z=THREE.MathUtils.clamp(carrier.pos.z+attack*carrier.speed*dt*.62,-54,54);carrier.pos.x=THREE.MathUtils.clamp(carrier.pos.x+Math.sin(performance.now()/650)*dt*.8,-23,23)}ball.position.copy(carrier.pos).add(new THREE.Vector3(.2,1.36,-.18));for(const p of defense){const dx=carrier.pos.x-p.pos.x,dz=carrier.pos.z-p.pos.z,dist=Math.hypot(dx,dz);if(dist<22&&dist>.9){p.pos.x+=dx/dist*dt*(p.speed*.55);p.pos.z+=dz/dist*dt*(p.speed*.55);p.root.rotation.y=Math.atan2(dx,dz)}if(dist<1.5&&Math.random()<dt*1.8){finishPlay((carrier.pos.z-state.playStartZ)*attack);return}}const gained=(carrier.pos.z-state.playStartZ)*attack;if(gained>=state.toGo||Math.abs(carrier.pos.z)>=53){finishPlay(gained);return}aiTimer+=dt;if((state.watch||state.offense==='away')&&aiTimer>5){finishPlay(gained+2+Math.random()*4)}}
