ector3(0,1.35,.4));if(state.watch)toast('AI OFFENSE · POWER RUN');else if(!state.practice)toast(state.offense==='home'?'SNAP! FIND A LANE':'DEFENSE · CLOSE THE GAP');else toast('REP LIVE · MAKE YOU
