function movePlayer(dt){if(!state.selected||state.phase!=='live'||state.watch)return;const p=state.selected;let x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyS')?1:0)-(keys.has('KeyW
')?1:0);if(!x&&!z)return;const v=new THREE.Vector3(x,0,z).normalize();const sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');p.pos.addScaledVector(v,p.speed*(sprint?1.55:1)*dt);p.pos.x=THREE.MathU
