function updateFieldPaint(){const home=teams[state.home],away=teams[state.away];endHome.material.color.set(home.dark);endAway.material.color.set(away.dark);homeEndText.material.dispose();homeEndText.material=stadiumText(home.short,74);awayEndText.material.dispose();awayEndText.material=stadiumText(away.mascot,70);}

const keys=new Set();let aiTimer=0,simAccumulator=0,weatherParticles=null;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space'&&state.screen==='game')snapBall();if(e.code==='Escape'&&state.screen==='game')pauseGame();if(/^Digit[1-4]$/.test(e.code)&&state.screen==='game'&&state.phase==='throwing')throwTo(+e.code.slice(-1)-1);});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

function startMode(watch=false){state.watch=watch;state.practice=state.mode==='Practice';state.resultRecorded=false;state.cameraMode=0;aiTimer=0;createTeamsOnField();setupWeather();state.screen='game';main.innerHTML=gameUI();if(state.practice){state.quarter=0;state.clock=0;state.homeScore=0;state.awayScore=0;state.phase='pre-snap';state.spot=25;state.down=1;state.toGo=10;toast('PRACTICE FIELD · WORK THE PLAY');}else toast(watch?'AI BROADCAST MODE':'FRIDAY NIGHT · GAME ON');camera.position.set(0,65,101);camera.lookAt(0,0,0);updateHUD();}
function gameUI(){const isPractice=state.practice;return `<div class="game-screen"><div class="scorebug"><div class="score-team home"><b>${teams[state.home].short}</b><small id="home-score">0</small></div><div class="score-center"><span id="game-clock">Q1&nbsp; 5:00</span><small>LEGION HIGH</small></div><div class="score-team"><b>${teams[state.away].short}</b><small id="away-score">0</small></div></div><div class="game-hud"><div class="hud-kicker">${isPractice?'PRACTICE · OFFENSE':`LEGION HIGH · ${state.offense==='home'?'OFFENSE':'DEFENSE'}`}</div><div class="hud-down" id="down-line">1ST &amp; 10</div><div class="hud-yard" id="yard-line">${yardLabel()}</div></div><div class="play-call" id="play-call">${state.watch?'AI COACHING':isPractice?'PRACTICE REP':state.play}<b id="phase-label">${state.watch?'WATCH THE DRIVE':'SPACE · SNAP THE BALL'}</b></div>${!state.watch&&!isPractice?`<div class="pass-targets" id="pass-targets" style="display:none"><button data-action="throw" data-target="0"><b>1</b> WIDE LEFT</button><button data-action="throw" data-target="1"><b>2</b> SLOT</button><button data-action="throw" data-target="2"><b>3</b> WIDE RIGHT</button><button data-action="throw" data-target="3"><b>4</b> BACK</button></div>`:''}<div class="game-controls"><span class="control-hint"><kbd>W A S D</kbd> MOVE</span><span class="control-hint"><kbd>SHIFT</kbd> SPRINT</span><span class="control-hint"><kbd>SPACE</kbd> SNAP / HUSTLE</span><span class="control-hint"><kbd>1–4</kbd> PASS</span></div><div class="mobile-controls"><button class="up" data-move="up">▲</button><button class="left" data-move="left">◀</button><button class="right" data-move="right">▶</button><button class="down" data-move="down">▼</button></div><div class="game-buttons"><button data-action="snap">▶ &nbsp;SNAP / NEXT</button><button data-action="playbook">▤ &nbsp;PLAY</button><button data-action="camera">◉ &nbsp;CAMERA</button><button data-action="stats">▥ &nbsp;STATS</button><button data-action="pause">Ⅱ &nbsp;PAUSE</button></div></div>`}
function yardLabel(){const yard=Math.max(1,Math.min(99,Math.round(state.spot)));return `${state.offense==='home'?'LEGION':'VISITORS'} ${yard} · ${state.toGo} TO GO`}
function clockString(){const m=Math.floor(Math.max(0,state.clock)/60),s=Math.max(0,state.clock)%60;return `${m}:${String(Math.floor(s)).padStart(2,'0')}`}
function updateHUD(){const el=document.querySelector('#down-line');if(el)el.innerHTML=state.practice?'PRACTICE REP':`${state.down}${state.down===1?'ST':state.down===2?'ND':state.down===3?'RD':'TH'} &amp; ${Math.max(1,Math.ceil(state.toGo))}`;const y=document.querySelector('#yard-line');if(y)y.textContent=yardLabel();const hs=document.querySelector('#home-score');if(hs)hs.textContent=state.homeScore;const as=document.querySelector('#away-score');if(as)as.textContent=state.awayScore;const cl=document.querySelector('#game-clock');if(cl)cl.innerHTML=state.practice?'TRAINING':`Q${state.quarter}&nbsp; ${clockString()}`;const ph=document.querySelector('#phase-label');if(ph)ph.textContent=state.phase==='pre-snap'?'SPACE · SNAP THE BALL':state.phase==='throwing'?'PRESS 1–4 TO PASS':state.phase==='live'?'BREAK THE TACKLE':state.phase==='dead'?'SPACE · NEXT PLAY':state.watch?'AI SIMULATION':'';const call=document.querySelector('#play-call');if(call){const tit=state.watch?'AI COACHING':state.practice?'PRACTICE REP':state.play;call.childNodes[0].textContent=tit}const targets=document.querySelector('#pass-targets');if(targets)targets.style.display=state.phase==='throwing'?'flex':'none';}

// Playable football state machine shared by Play and Watch: snap, move, pass, tackle, down, turnover, score.
function snapBall(){if(state.screen!=='game')return;if(state.phase==='pre-snap'||state.phase==='dead'){if(state.gameOver){showEndgame();return}aiTimer=0;state.phase='live';const offensePlayers=state.offense==='home'?state.offensePlayers:state.defensePlayers;const defensePlayers=state.offense==='home'?state.defensePlayers:state.offensePlayers;state.ballCarrier=offensePlayers[8];state.selected=state.watch?state.ballCarrier:(state.offense==='home'||state.practice?state.ballCarrier:defensePlayers[7]);state.playStartZ=state.ballCarrier.pos.z;ball.position.copy(state.ballCarrier.pos).add(new THREE.Vector3(0,1.35,.4));if(state.watch)toast('AI OFFENSE · POWER RUN');else if(!state.practice)toast(state.offense==='home'?'SNAP! FIND A LANE':'DEFENSE · CLOSE THE GAP');else toast('REP LIVE · MAKE YOUR MOVE');updateHUD();return}if(state.phase==='live'&&!state.practice&&!state.watch&&state.offense==='home'){state.phase='throwing';updateHUD();toast('RECEIVERS RELEASED · PICK A TARGET')}}
function throwTo(index){if(state.phase!=='throwing')return;const receivers=[state.offensePlayers[10],state.offensePlayers[7],state.offensePlayers[6],state.offensePlayers[9]];state.passTarget=receivers[index];state.ballFlight={from:ball.position.clone(),to:state.passTarget.pos.clone().add(new THREE.Vector3(0,1.8,-1)),t:0,duration:.85,index};state.phase='pass-flight';updateHUD();}
function nextPlay(reason,turnover=false){if(state.phase==='dead'&&reason==='dead')return;state.phase='dead';state.ballCarrier=null;state.ballFlight=null;if(ball)ball.position.set(0,.35,0);if(state.practice){state.down++;state.toGo=10;state.spot=25;setTimeout(()=>{if(state.screen==='game'){state.phase='pre-snap';updateHUD()}},900);toast('REP COMPLETE · RUN IT AGAIN');updateHUD();return}
 if(turnover){state.offense=state.offense==='home'?'away':'home';state.spot=100-state.spot;state.down=1;state.toGo=10;toast('TURNOVER ON DOWNS · CHANGE OF POSSESSION');resetFormations();updateHUD();return}
 if(state.spot>=100){if(state.offense==='home')state.homeScore+=7;else state.awayScore+=7;toast('TOUCHDOWN! SIX FOR THE HOME CROWD');state.phase='score';state.gameOver=false;updateHUD();setTimeout(()=>{if(state.screen==='game'){kickoff();updateHUD()}},1800);return}
 if(state.spot<=0){if(state.offense==='home')state.awayScore+=2;else state.homeScore+=2;toast('SAFETY · DEFENSE GETS TWO');kickoff();updateHUD();return}
 if(state.spot>=state.driveStart+state.toGo){state.down=1;state.toGo=10;state.driveStart=state.spot;toast('FIRST DOWN · MOVE THE CHAINS')}else if(state.down>=4){if(state.spot>=60&&Math.random()<.54){if(state.offense==='home')state.homeScore+=3;else state.awayScore+=3;toast('FIELD GOAL IS GOOD · THREE POINTS');kickoff();updateHUD();return}state.offense=state.offense==='home'?'away':'home';state.spot=100-state.spot;state.down=1;state.toGo=10;state.driveStart=state.spot;toast('TURNOVER ON DOWNS · CHANGE OF POSSESSION');resetFormations();updateHUD();return}else{state.down++;state.toGo=Math.max(1,state.toGo-(state.spot-state.lastSpot))}
 resetFormations();updateHUD();}
function kickoff(){if(state.gameOver)return;state.offense=state.offense==='home'?'away':'home';state.spot=25;state.driveStart=25;state.down=1;state.toGo=10;state.phase='pre-snap';state.possessions++;resetFormations();if(state.quarter>=4&&state.clock<=0){state.gameOver=true;showEndgame()} }
function resetFormations(){const home=state.offensePlayers,away=state.defensePlayers;if(!home||!away)return;const off=state.offense==='home'?home:away,def=state.offense==='home'?away:home;const direction=state.offense==='home'?-1:1;const line=state.offense==='home'?50-state.spot:state.spot-50;off.forEach((p,i)=>{const slots=[[-18,1],[-12,1],[-6,1],[0,1],[6,1],[12,1],[18,1],[-3,4],[0,7],[12,8],[-14,9]][i];p.pos.set(slots[0],.02,line+slots[1]);p.root.rotation.y=direction<0?0:Math.PI});def.forEach((p,i)=>{const slots=[[-18,-2],[-12,-2],[-6,-2],[0,-2],[6,-2],[12,-2],[18,-2],[-14,-8],[-5,-7],[6,-8],[16,-8]][i];p.pos.set(slots[0],.02,line+slots[1]);p.root.rotation.y=direction<0?Math.PI:0});state.selected=state.offense==='home'?off[8]:def[7];state.phase='pre-snap';state.driveStart=state.spot;aiTimer=0;updateHUD()}
function endQuarter(){if(state.practice)return;if(state.quarter<4){state.quarter++;state.clock=state.quarterLength*60;toast(`END OF QUARTER · ${state.homeScore}–${state.awayScore}`)}else{state.gameOver=true;showEndgame()}}
function showEndgame(){state.phase='dead';const won=state.homeScore>state.awayScore,tied=state.homeScore===state.awayScore;if(!state.resultRecorded){if(state.gameOrigin==='season'){if(won)state.wins++;else if(!tied)state.losses++;state.seasonWeek=Math.min(11,state.seasonWeek+1)}else if(state.gameOrigin==='career'&&!tied){state.career.prestige=Math.min(5,state.career.prestige+(won?1:0))}state.resultRecorded=true}const result=tied?'A FRIDAY NIGHT DRAW':won?'VICTORY AT LEGION HIGH':'FINAL WHISTLE';modal(result,`${teams[state.home].name} ${state.homeScore} · ${state.awayScore} ${teams[state.away].name}`,`The Friday night lights are still shining at Legion High Stadium. ${won?'The Knights take another step toward the postseason.':tied?'Both teams leave with work to do.':'Every Friday brings another chance to grow.'}`,[{label:state.gameOrigin?'RETURN TO MODE HUB':'RETURN TO HOME',action:'return-origin',primary:true},{label:'PLAY AGAIN',action:'replay'}]);}
function movePlayer(dt){if(!state.selected||state.phase!=='live'||state.watch)return;const p=state.selected;let x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0);if(!x&&!z)return;const v=new THREE.Vector3(x,0,z).normalize();const sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');p.pos.addScaledVector(v,p.speed*(sprint?1.55:1)*dt);p.pos.x=THREE.MathUtils.clamp(p.pos.x,-24,24);p.pos.z=THREE.MathUtils.clamp(p.pos.z,-55,55);p.root.rotation.y=Math.atan2(v.x,v.z);p.phase+=dt*13;p.legs[0].rotation.x=Math.sin(p.phase)*.65;p.legs[1].rotation.x=-Math.sin(p.phase)*.65;if(state.ballCarrier===p)ball.position.copy(p.pos).add(new THREE.Vector3(.2,1.36,-.18));}
function finishPlay(gained){if(state.phase!=='live')return;state.lastSpot=state.spot;state.spot=THREE.MathUtils.clamp(state.spot+gained,0,100);if(state.spot>=100){if(state.offense==='home')state.homeScore+=7;else state.awayScore+=7;state.phase='score';state.ballCarrier=null;toast('TOUCHDOWN! SIX FOR THE OFFENSE');updateHUD();setTimeout(()=>{if(state.screen==='game'){kickoff();updateHUD()}},1600);return}nextPlay('tackle')}
function aiMove(dt){if(state.phase!=='live')return;const carrier=state.ballCarrier;if(!carrier)return;const attack=state.offense==='home'?-1:1;const defense=state.offense==='home'?state.defensePlayers:state.offensePlayers;if(state.watch||state.offense==='away'){carrier.pos.z=THREE.MathUtils.clamp(carrier.pos.z+attack*carrier.speed*dt*.62,-54,54);carrier.pos.x=THREE.MathUtils.clamp(carrier.pos.x+Math.sin(performance.now()/650)*dt*.8,-23,23)}ball.position.copy(carrier.pos).add(new THREE.Vector3(.2,1.36,-.18));for(const p of defense){const dx=carrier.pos.x-p.pos.x,dz=carrier.pos.z-p.pos.z,dist=Math.hypot(dx,dz);if(dist<22&&dist>.9){p.pos.x+=dx/dist*dt*(p.speed*.55);p.pos.z+=dz/dist*dt*(p.speed*.55);p.root.rotation.y=Math.atan2(dx,dz)}if(dist<1.5&&Math.random()<dt*1.8){finishPlay((carrier.pos.z-state.playStartZ)*attack);return}}const gained=(carrier.pos.z-state.playStartZ)*attack;if(gained>=state.toGo||Math.abs(carrier.pos.z)>=53){finishPlay(gained);return}aiTimer+=dt;if((state.watch||state.offense==='away')&&aiTimer>5){finishPlay(gained+2+Math.random()*4)}}
function updateBall(dt){if(state.phase==='pass-flight'&&state.ballFlight){const f=state.ballFlight;f.t+=dt;const t=Math.min(1,f.t/f.duration);ball.position.lerpVectors(f.from,f.to,t);ball.position.y+=Math.sin(t*Math.PI)*5;ball.rotation.x+=dt*10;if(t>=1){const catchChance=state.difficulty==='Rookie'?.88:state.difficulty==='Varsity'?.69:.52;if(Math.random()<catchChance){state.ballCarrier=state.passTarget;state.selected=state.passTarget;state.phase='live';toast('COMPLETE! RECEIVER IN SPACE');}else{state.phase='dead';toast('INCOMPLETE PASS · SECOND DOWN');state.down++;state.toGo=10;setTimeout(()=>{if(state.screen==='game'){resetFormations();updateHUD()}},900)}state.ballFlight=null;updateHUD()}}}
function updateWeather(dt){if(state.weather==='Rain'&&weatherParticles){const a=weatherParticles.geometry.attributes.position.array;for(let i=0;i<a.length;i+=3){a[i+1]-=dt*32;if(a[i+1]<0){a[i+1]=35;a[i]=THREE.MathUtils.randFloatSpread(110);a[i+2]=THREE.MathUtils.randFloatSpread(120)}}weatherParticles.geometry.attributes.position.needsUpdate=true}}
function setupWeather(){if(weatherParticles){scene.remove(weatherParticles);weatherParticles.geometry.dispose();weatherParticles.material.dispose();weatherParticles=null}scene.fog.density=state.weather==='Fog'?.011:.0036;scene.fog.color.set(state.weather==='Fog'?'#899493':'#82979a');if(state.weather==='Rain'){const pos=new Float32Array(1500*3);for(let i=0;i<pos.length;i+=3){pos[i]=THREE.MathUtils.randFloatSpread(110);pos[i+1]=Math.random()*35;pos[i+2]=THREE.MathUtils.randFloatSpread(120)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));weatherParticles=new THREE.Points(geo,new THREE.PointsMaterial({color:'#c4d6dc',size:.09,transparent:true,opacity:.65}));scene.add(weatherParticles)}}
function tick(){requestAnimationFrame(tick);const dt=Math.min(.04,clock3.getDelta());if(state.screen==='game'){if(state.watch&&state.phase==='pre-snap'){aiTimer+=dt;if(aiTimer>1.25)snapBall()}movePlayer(dt);aiMove(dt);updateBall(dt);updateWeather(dt);updateGameCamera(dt);if(!state.practice&&!state.gameOver){state.clock=Math.max(0,state.clock-dt);if(state.clock<=0)endQuarter();}simAccumulator+=dt;if(simAccumulator>.35){simAccumulator=0;updateHUD();}}
 for(const p of players){if(p.active){p.phase+=dt*(state.phase==='live'?8:2);if(state.phase==='live'&&p!==state.selected){p.legs[0].rotation.x=Math.sin(p.phase)*.18;p.legs[1].rotation.x=-Math.sin(p.phase)*.18}}}
 renderer.render(scene,camera)}const clock3=new THREE.Clock();tick();

function homeScreen(){return `<section class="home-layout"><div class="eyebrow">FRIDAY NIGHT LIGHTS · EST. 1968</div><h1 class="hero-title">THE GAME<br><span>IS OURS.</span></h1><p class="hero-desc">Build a program. Own the rivalry. Take the field under the lights at Legion High Stadium.</p><div class="home-actions"><button class="action-card" data-action="quick"><span class="action-icon">▶</span><span class="action-copy"><b>QUICK GAME</b><small>SET THE MATCHUP. TAKE THE FIELD.</small></span><span class="action-arrow">↗</span></button><button class="action-card" data-action="season"><span class="action-icon">▤</span><span class="action-copy"><b>SEASON</b><small>CHASE A LEAGUE TITLE, ONE FRIDAY AT A TIME.</small></span><span class="action-arrow">↗</span></button><button class="action-card" data-action="career"><span class="action-icon">♜</span><span class="action-copy"><b>COACH CAREER</b><small>BUILD YOUR LEGACY AT LEGION HIGH.</small></span><span class="action-arrow">↗</span></button><button class="action-card" data-action="more"><span class="action-icon">＋</span><span class="action-copy"><b>MORE MODES</b><small>WATCH · TOURNAMENT · PRACTICE</small></span><span class="action-arrow">↗</span></button></div><div class="home-bottom"><b class="crest">L</b><span>LEGION HIGH STADIUM</span><span>HOME OF THE KNIGHTS</span></div></section><aside class="right-rail"><div class="rail-label">WEEK 01 · THE RIVALRY</div><div class="rivalry">THE COUNTY LINE CLASSIC</div><div class="rail-meta">Legion Knights vs. Cedar Ridge Wolves</div><div class="rail-record"><div><b>32</b><small>YEARS RUNNING</small></div><div><b>18–14</b><small>ALL-TIME SERIES</small></div></div></aside>`}
function shell(title,subtitle,content,back='home'){return `<section class="screen-wrap"><div class="screen-heading"><div><div class="eyebrow">LEGION HIGH STADIUM</div><h1>${title}</h1><p>${subtitle}</p></div><button class="back-btn" data-action="${back}">← &nbsp;BACK</button></div>${content}</section>`}
function quickScreen(){return shell('QUICK GAME','Set the Friday night matchup. Every game is played at Legion High Stadium.',`<div class="quick-grid"><div class="panel config-panel"><h2 class="section-label">THE MATCHUP</h2><div class="team-row"><div class="team-tile"><small>HOME TEAM</small><select id="home-team">${teams.map((t,i)=>`<option value="${i}" ${state.home===i?'selected':''}>${t.name} · ${t.mascot}</option>`).join('')}</select></div><span class="vs">VS</span><div class="team-tile"><small>AWAY TEAM</small><select id="away-team">${teams.map((t,i)=>`<option value="${i}" ${state.away===i?'selected':''}>${t.name} · ${t.mascot}</option>`).join('')}</select></div></div><div class="form-row"><div class="form-field"><label>WEATHER</label><select class="select-control" id="weather">${['Clear','Rain','Fog'].map(x=>`<option ${state.weather===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>DIFFICULTY</label><select class="select-control" id="difficulty">${['Rookie','Varsity','All-State'].map(x=>`<option ${state.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="form-row"><div class="form-field"><label>QUARTER LENGTH</label><div class="segmented">${[3,5,8].map(n=>`<button data-length="${n}" class="${state.quarterLength===n?'active':''}">${n} MIN</button>`).join('')}</div></div><div class="form-field"><label>GAME PRESENTATION</label><div class="segmented"><button class="active">FRIDAY NIGHT</button></div></div></div><p class="choice-note">High-school rules, four quarters, and a shared hometown stadium. Pick your sideline before kickoff.</p></div><div class="panel game-preview"><div class="stadium-mini"></div><div class="preview-top"><div class="preview-kicker">WEEK 01 · NON-CONFERENCE</div><div class="preview-matchup"><span id="preview-home">${teams[state.home].short}</span><br>VS<br><span id="preview-away">${teams[state.away].short}</span></div><div class="preview-detail">LEGION HIGH STADIUM &nbsp;·&nbsp; ${state.quarterLength} MIN QUARTERS</div></div><div class="preview-bottom"><button class="primary-btn" data-action="play-choice">PLAY GAME &nbsp;→</button><button class="ghost-btn" data-action="watch-start">WATCH</button></div></div></div>`,'home')}
function moreScreen(){return shell('CHOOSE YOUR NIGHT','Every mode shares the same teams, rules, and Legion High Stadium.',`<div class="mode-choice"><button class="mode-card" data-action="watch-start"><span class="mode-icon">◉</span><b>WATCH</b><small>Let both sidelines play. Follow the game from the broadcast camera.</small></button><button class="mode-card" data-action="tournament"><span class="mode-icon">♜</span><b>TOURNAMENT</b><small>Build a four-school playoff bracket and chase the trophy.</small></button><button class="mode-card" data-action="practice"><span class="mode-icon">◎</span><b>PRACTICE</b><small>Work the offense, find a lane, and get reps under the lights.</small></button><button class="mode-card" data-action="season"><span class="mode-icon">▤</span><b>SEASON</b><small>Play through a ten-week high-school season.</small></button></div>`,'home')}
function seasonScreen(){const schedule=['Cedar Ridge','North Valley','Westfield Prep','Pine Creek','Cedar Ridge','Westfield Prep','North Valley','Pine Creek','Cedar Ridge','STATE CHAMPIONSHIP'];return shell('SEASON HUB',`LEGION KNIGHTS · ${state.wins}–${state.losses} · WEEK ${state.seasonWeek} OF 10`,`<div class="panel wide-panel"><div class="data-grid"><div><h2 class="section-label">2025 VARSITY SCHEDULE</h2><div class="week-list">${schedule.map((op,i)=>`<div class="week-row ${i+1===state.seasonWeek?'current':''}"><small>WEEK ${String(i+1).padStart(2,'0')}</small><b>${i+1<10?'vs. ':''}${op}</b><span>${i+1<state.seasonWeek?(i%2?'W':'L'):i+1===state.seasonWeek?'UP NEXT':'—'}</span></div>`).join('')}</div></div><aside class="season-side"><h2 class="section-label">PROGRAM STATUS</h2><div class="stat-card"><small>LEAGUE RECORD</small><b>${state.wins} – ${state.losses}</b></div><div class="stat-card"><small>TEAM RATING</small><b>84 <span style="font:600 11px 'DM Sans';color:#afbfbb">VARSITY</span></b></div><div class="stat-card"><small>PLAYOFF OUTLOOK</small><b>${state.wins>=5?'IN THE HUNT':'BUILDING'}</b></div><button class="primary-btn wide" data-action="season-game">${state.seasonWeek>10?'SEASON COMPLETE':'PLAY WEEK '+String(state.seasonWeek).padStart(2,'0')} →</button><p class="choice-note">After the final whistle, return here to track standings, progress, and the next matchup.</p></aside></div></div>`,'home')}
function careerScreen(){return shell('COACH CAREER','A legacy starts with one practice, one player, one Friday night.',`<div class="panel wide-panel"><div class="data-grid"><div><h2 class="section-label">LEGION KNIGHTS · PROGRAM BUILDER</h2><p class="choice-note" style="font-size:12px;max-width:520px">Take over a hometown program and grow it into a contender. Develop your roster, earn local prestige, and make the county remember your name.</p><div class="stat-card"><small>COACH</small><b>J. MORGAN <span style="font:600 11px 'DM Sans';color:#afbfbb">· HEAD COACH</span></b></div><div class="stat-card"><small>PROGRAM PRESTIGE</small><b>${state.career.prestige} <span style="font:600 11px 'DM Sans';color:#afbfbb">/ 5</span></b></div><button class="primary-btn" data-action="career-game">START FRIDAY NIGHT →</button></div><div><h2 class="section-label">VARSITY ROSTER</h2>${roster.slice(0,6).map((r,i)=>`<div class="roster-row"><span class="jersey">${r[2]}</span><div><b>${r[0]}</b><small>${r[1]} · ${i<3?'OFFENSE':'SKILL GROUP'}</small></div><span class="ovr">${r[3]}</span></div>`).join('')}<button class="ghost-btn" style="width:100%;margin-top:10px" data-action="develop">PLAYER DEVELOPMENT · ${state.career.points} POINTS</button></div></div></div>`,'home')}
function tournamentScreen(){return shell('COUNTY PLAYOFF','Four schools. One bracket. One Friday-night champion.',`<div class="panel wide-panel"><h2 class="section-label">SEMIFINAL BRACKET</h2><div class="data-grid"><div class="week-list"><div class="week-row current"><small>SEMIFINAL 1</small><b>Legion High vs. Cedar Ridge</b><span>READY</span></div><div class="week-row"><small>SEMIFINAL 2</small><b>North Valley vs. Westfield Prep</b><span>UP NEXT</span></div><div class="week-row"><small>FINAL</small><b>Championship Friday</b><span>—</span></div></div><div class="season-side"><div class="stat-card"><small>LOCATION</small><b>LEGION HIGH STADIUM</b></div><div class="stat-card"><small>FORMAT</small><b>SINGLE ELIMINATION</b></div><button class="primary-btn wide" data-action="tournament-game">PLAY SEMIFINAL →</button></div></div></div>`,'home')}
function render(){if(state.screen==='home'){main.innerHTML=homeScreen();return}if(state.screen==='quick'){main.innerHTML=quickScreen();return}if(state.screen==='more'){main.innerHTML=moreScreen();return}if(state.screen==='season'){main.innerHTML=seasonScreen();return}if(state.screen==='career'){main.innerHTML=careerScreen();return}if(state.screen==='tournament'){main.innerHTML=tournamentScreen();return}}
function go(screen){state.screen=screen;render()}
function modal(title,subtitle,body,actions=[]){const old=document.querySelector('.modal-shade');if(old)old.remove();const shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML=`<div class="modal"><div class="eyebrow">LEGION HIGH STADIUM</div><h2>${title}</h2><p><b style="color:#e4bf70">${subtitle}</b></p><p>${body}</p><div class="modal-actions">${actions.map(a=>`<button class="${a.primary?'primary-btn':'ghost-btn'}" data-action="${a.action}">${a.label}</button>`).join('')}</div></div>`;app.appendChild(shade)}
function pauseGame(){if(state.screen!=='game')return;modal('GAME PAUSED',`${teams[state.home].short} ${state.homeScore} · ${state.awayScore} ${teams[state.away].short}`,'Take a breath, Coach. The lights will be waiting when you are ready.',[{label:'RETURN TO GAME',action:'resume',primary:true},{label:'END GAME',action:'home'}])}
function showStats(){modal('FRIDAY NIGHT STATS',`${teams[state.home].short} ${state.homeScore} · ${state.awayScore} ${teams[state.away].short}`,`Quarter ${state.quarter} · ${clockString()} remaining<br>Down ${state.down}, ${Math.ceil(state.toGo)} to go · Ball at ${yardLabel()}<br>Team ratings: ${teams[state.home].rating} vs. ${teams[state.away].rating}`,[{label:'BACK TO GAME',action:'resume',primary:true}])}
function choosePlay(){modal('PICK YOUR PLAY','OFFENSIVE PLAYBOOK','Choose a call. You can run the ball or release your receivers after the snap.',[{label:'POWER RUN',action:'runplay'},{label:'PLAY-ACTION PASS',action:'passplay',primary:true}])}
function handleAction(action,el){if(action==='return-origin'){document.querySelector('.modal-shade')?.remove();const destination=state.gameOrigin||'home';state.watch=false;state.practice=false;state.screen=destination;render();return}if(action==='home'){document.querySelector('.modal-shade')?.remove();state.screen='home';state.watch=false;state.practice=false;render();return}if(action==='quick'){go('quick');return}if(action==='more'){go('more');return}if(action==='season'){go('season');return}if(action==='career'){go('career');return}if(action==='tournament'){go('tournament');return}if(action==='play-choice'){state.mode='Quick Game';state.gameOrigin='quick';modal('HOW DO YOU WANT TO EXPERIENCE IT?','FRIDAY NIGHT · LEGION HIGH STADIUM','Play the Knights yourself or watch the AI take both sidelines. Both use the same football engine and game rules.',[{label:'WATCH THE GAME',action:'watch-start'},{label:'PLAY THE GAME',action:'play-start',primary:true}]);return}if(action==='play-start'){document.querySelector('.modal-shade')?.remove();state.gameOrigin='quick';startMode(false);return}if(action==='watch-start'){if(state.screen!=='game')state.gameOrigin=state.screen;document.querySelector('.modal-shade')?.remove();state.mode='Watch';startMode(true);return}if(action==='practice'){state.gameOrigin=state.screen;state.mode='Practice';state.home=0;state.away=1;state.weather='Clear';startMode(false);return}if(action==='season-game'){state.mode='Season';const op=[1,3,2,4,1,2,3,4,1,3][Math.min(9,state.seasonWeek-1)];state.home=0;state.away=op;state.quarterLength=3;state.gameOrigin='season';modal('WEEK '+String(state.seasonWeek).padStart(2,'0'),`LEGION KNIGHTS vs. ${teams[op].name}`,'Play or watch this week’s game. Your season record updates at the final whistle.',[{label:'WATCH',action:'season-watch'},{label:'PLAY GAME',action:'season-play',primary:true}]);return}if(action==='season-play'||action==='season-watch'){const watch=action==='season-watch';document.querySelector('.modal-shade')?.remove();state.mode='Season';state.watch=watch;startMode(watch);return}if(action==='career-game'){state.mode='Career';state.home=0;state.away=1;state.quarterLength=3;state.gameOrigin='career';startMode(false);return}if(action==='tournament-game'){state.mode='Tournament';state.home=0;state.away=1;state.quarterLength=3;state.gameOrigin='tournament';startMode(false);return}if(action==='replay'){document.querySelector('.modal-shade')?.remove();if(state.mode==='Season')state.gameOrigin='season';startMode(state.watch);return}if(action==='resume'){document.querySelector('.modal-shade')?.remove();return}if(action==='pause'){pauseGame();return}if(action==='snap'){snapBall();return}if(action==='stats'){showStats();return}if(action==='playbook'){choosePlay();return}if(action==='camera'){state.cameraMode=(state.cameraMode||0)+1;camera.position.set(state.cameraMode%2?54:0,state.cameraMode%2?42:65,state.cameraMode%2?78:101);camera.lookAt(0,0,0);toast(state.cameraMode%2?'SIDELINE CAMERA':'HIGH COACH CAM');return}if(action==='runplay'){document.querySelector('.modal-shade')?.remove();state.play='I-Formation · Power';toast('PLAY SELECTED · POWER');return}if(action==='passplay'){document.querySelector('.modal-shade')?.remove();state.play='Shotgun · Four Verticals';toast('PLAY SELECTED · FOUR VERTICALS');return}if(action==='throw'){throwTo(Number(el.dataset.target));return}if(action==='develop'){state.career.points=Math.max(0,state.career.points-1);state.career.prestige=Math.min(5,state.career.prestige+1);toast('ROSTER WORK · PROGRAM PRESTIGE UP');go('career');return}}
main.addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]');if(actionEl){handleAction(actionEl.dataset.action,actionEl);return}const lengthEl=e.target.closest('[data-length]');if(lengthEl){state.quarterLength=Number(lengthEl.dataset.length);document.querySelectorAll('[data-length]').forEach(x=>x.classList.toggle('active',x===lengthEl));const detail=document.querySelector('.preview-detail');if(detail)detail.textContent=`LEGION HIGH STADIUM · ${state.quarterLength} MIN QUARTERS`;return}const moveEl=e.target.closest('[data-move]');if(moveEl){const code={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD'}[moveEl.dataset.move];keys.add(code);setTimeout(()=>keys.delete(code),150);}});
main.addEventListener('change',e=>{if(e.target.id==='home-team'){state.home=Number(e.target.value);if(state.home===state.away)state.away=(state.home+1)%teams.length;refreshQuick()}if(e.target.id==='away-team'){state.away=Number(e.target.value);if(state.home===state.away)state.home=(state.away+1)%teams.length;refreshQuick()}if(e.target.id==='weather'){state.weather=e.target.value;setupWeather()}if(e.target.id==='difficulty')state.difficulty=e.target.value});
function refreshQuick(){if(state.screen==='quick')render()}
main.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-move]');if(!b)return;const code={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];keys.add(code);b.setPointerCapture?.(e.pointerId)});
main.addEventListener('pointerup',e=>{const b=e.target.closest('[data-move]');if(!b)return;const code={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];keys.delete(code)});
document.querySelector('.brand').addEventListener('click',()=>{state.screen='home';render()});

