function snapBall(){if(state.screen!=='game')return;if(state.phase==='pre-snap'||state.phase==='dead'){if(state.gameOver){showEndgame();return}aiTimer=0;state.phase='live';const offensePlayers=state.offense==='home'?state.offensePlayers:state.defensePlayers;const defensePlayers=state.offense==='home'?state.defensePlayers:state.offensePlayers;state.ballCarrier=offensePlayers[8];state.selected=state.watch?state.ballCarrier:(state.offense==='home'||state.practice?state.ballCarrier:defensePlayers[7]);state.playStartZ=state.ballCarrier.pos.z;ball.position.copy(state.ballCarrier.pos).add(new THREE.Vector3(0,1.35,.4));if(state.watch)toast('AI OFFENSE · POWER RUN');else if(!state.practice)toast(state.offense==='home'?'SNAP! FIND A LANE':'DEFENSE · CLOSE THE GAP');else toast('REP LIVE · MAKE YOUR MOVE');updateHUD();return}if(state.phase==='live'&&!state.practice&&!state.watch&&state.offense==='home'&&state.ballCarrier===state.selected){state.phase='throwing';updateHUD();toast('RECEIVERS RELEASED · PICK A TARGET')}}
function throwTo(index){if(state.phase!=='throwing')return;const receivers=[state.offensePlayers[10],state.offensePlayers[7],state.offensePlayers[6],state.offensePlayers[9]];state.passTarget=receivers[index];state.ballFlight={from:ball.position.clone(),to:state.passTarget.pos.clone().add(new THREE.Vector3(0,1.8,-1)),t:0,duration:.85,index};state.phase='pass-flight';updateHUD();}
function nextPlay(reason,turnover=false){if(state.phase==='dead'&&reason==='dead')return;state.phase='dead';state.ballCarrier=null;state.ballFlight=null;if(ball)ball.position.set(0,.35,0);if(state.practice){state.down++;state.toGo=10;state.spot=25;setTimeout(()=>{if(state.screen==='game'){state.phase='pre-snap';updateHUD()}},900);toast('REP COMPLETE · RUN IT AGAIN');updateHUD();return}
 if(turnover){state.offense=state.offense==='home'?'away':'home';state.spot=100-state.spot;state.down=1;state.toGo=10;toast('TURNOVER ON DOWNS · CHANGE OF POSSESSION');resetFormations();updateHUD();return}

